// AUTO-GENERATED by `mise run gen-types`. Do not edit manually.
type Amount = string; // rust_decimal money — always a decimal string

/**
 * One side of a movement: one of the user's own stores, a saved contact (and
 * optionally one of its accounts), or free text.
 */
type AccountRef = { "store": string } | { "contact": { contact_id: string, account_id: string | null, } } | { "raw": string };

type AlertCondition = "above" | "below";

type AnalyticsReport = { "cashflow": CashflowReport } | { "year": YearReport } | { "categories": CategoriesReport } | { "networth": NetworthReport } | { "stores": StoresReport } | { "pnl": PnlReport } | { "portfolio": PortfolioReport } | { "inflation": InflationReport } | { "losses": LossReport };

/**
 * Preferences that follow the *user*, not the vault: they must survive opening
 * a different vault, so they are stored next to the app, not inside the doc.
 */
type AppSettings = { theme: Theme, locale: Locale, 
/**
 * ISO 4217 code the whole portfolio is valued in (e.g. `usd`, `rub`).
 */
base_currency: string, 
/**
 * Currencies offered on hover next to any price. Empty = no tooltip.
 */
favorite_currencies: Array<string>, 
/**
 * IANA zone days and months are cut in (plan §7.6); `None` = the OS zone.
 */
timezone: string | null, 
/**
 * Annual inflation, percent, by lowercase currency code (plan §6.5).
 * Used only by analytics, for «in today's money»; marked as reference.
 */
inflation: { [key: string]: Amount }, 
/**
 * Consent to send transaction hashes to public explorers (plan §8.2);
 * `None` = not asked yet.
 */
enrichment_opt_in: boolean | null, };

/**
 * Shared asset identification, so each variant does not repeat five
 * optional fields it does not always need.
 */
type AssetIdent = { symbol: string, name: string, coingecko_id: string | null, chain: Chain | null, contract: string | null, };

/**
 * Loose asset identification: enough to rebuild an [`AssetRef`] cache key
 * without making the frontend construct a full `quote` field.
 */
type AssetPriceInput = { symbol: string, coingecko_id: string | null, chain: Chain | null, contract: string | null, 
/**
 * RFC3339 moment to price at; empty means now.
 */
at: string | null, };

type AssetRef = { symbol: string, name: string, 
/**
 * e.g. `bitcoin` — used by CoinGecko.
 */
coingecko_id: string | null, chain: Chain | null, 
/**
 * Token contract address (for tokens on EVM/Solana-like networks).
 */
contract: string | null, 
/**
 * `base` quote currency symbol for FX peers (e.g. `usd`, `eur`).
 * For crypto this is the network quote (e.g. `btc`, `eth`).
 * Kept authoritative for display only.
 */
quote: string, };

type AssetSearchHit = { symbol: string, name: string, coingecko_id: string | null, chain: Chain | null, contract: string | null, 
/**
 * CoinGecko market-cap rank (0 = unknown).
 */
rank: bigint, };

/**
 * Selling a non-financial asset (a flat, a car) out of an `asset` store.
 */
type AssetSellTx = { meta: TxMeta, store_id: string, asset: AssetRef, unit_price: Amount, quantity: Amount, 
/**
 * Currency of `unit_price` and of the proceeds.
 */
currency: AssetRef, 
/**
 * Store that received the money, if it is tracked.
 */
proceeds_to: string | null, fee: Fee | null, 
/**
 * Price of the currency, for valuing the proceeds.
 */
price: PriceStamp, };

type AssetStat = { asset: AssetRef, quantity: Amount, price_usd: Amount, value_usd: Amount, };

type Automation = { id: string, name: string, active: boolean, schedule: Schedule, 
/**
 * First planned date, RFC3339.
 */
starts_at: string, template: TransactionDraft, 
/**
 * Last planned date already processed (created or rejected).
 */
last_planned_at: string | null, created_at: string, };

/**
 * An automation as the form edits it. The template is an ordinary
 * transaction input of one of the four verbs.
 */
type AutomationInput = { name: string, active: boolean, schedule: Schedule, 
/**
 * RFC3339, the first planned date.
 */
starts_at: string, template: TransactionInput, };

type AutomationOutcome = { "created": { tx_id: string, } } | { "rejected": { reason: RejectReason, } } | "skipped";

/**
 * The outcome of one scheduler pass.
 */
type AutomationPass = { 
/**
 * Ids of the transactions created.
 */
created: Array<string>, 
/**
 * Runs rejected in this pass, for the notification.
 */
rejected: Array<AutomationRun>, 
/**
 * Missed dates beyond the catch-up limit, recorded as skipped.
 */
skipped: number, };

/**
 * Payload of `automation-rejected`: one run the scheduler could not create.
 */
type AutomationRejectedEvent = { run_id: string, automation_id: string, name: string, planned_at: string, reason: RejectReason, };

/**
 * One processed planned date of an automation. Never retried automatically;
 * doubles as the automation's history.
 */
type AutomationRun = { id: string, automation_id: string, planned_at: string, processed_at: string, outcome: AutomationOutcome, };

type Budget = { id: string, active: boolean, target: BudgetTarget, period: BudgetPeriod, limit: Amount, currency: string, };

type BudgetInput = { active: boolean, target: BudgetTarget, period: BudgetPeriod, limit: Amount, currency: string, };

type BudgetPeriod = "day" | "week" | "month";

/**
 * A limit and how much of it the current period used.
 */
type BudgetStatus = { budget: Budget, 
/**
 * Spent in the current period, in the budget's own currency.
 */
spent: Amount, remaining: Amount, 
/**
 * `spent / limit`, 0 when the limit is zero.
 */
used: Amount, period_start: string, period_end: string, };

type BudgetTarget = "total" | { "category": string } | { "store": StoreScope };

/**
 * Product type. Bybit requires this on most private endpoints.
 */
type BybitCategory = "spot" | "linear" | "inverse";

/**
 * A fill as offered in the "recent trades" dropdown.
 */
type BybitExecution = { symbol: string, side: string, order_type: string, exec_price: string, exec_qty: string, exec_value: string, exec_fee: string, exec_time: string, is_maker: boolean, 
/**
 * Pre-shaped form values, so the frontend never re-derives the swap.
 */
prefill: TradePrefill, };

type BybitExecutionsInput = { category: BybitCategory, symbol: string | null, limit: number | null, store_id: string | null, };

/**
 * Never fails: an unconfigured or unreachable key yields an empty list.
 */
type BybitExecutionsResult = { executions: Array<BybitExecution>, notice: string | null, };

/**
 * Cached USD quote nearest the asked moment. `ts` is when that rate was
 * taken, empty when the asset was never priced; a hand-set price and USD
 * itself hold for all time and carry the asked moment.
 */
type CachedPrice = { price_usd: Amount, ts: string, };

/**
 * Raw calculator inputs. The UI is expected to pass empty/zero values while
 * the user is still typing — every field is optional in practice.
 */
type CalcInput = { mode: CalcMode, 
/**
 * Source asset symbol, display only.
 */
from_symbol: string, 
/**
 * Target asset symbol, display only.
 */
to_symbol: string, 
/**
 * `Converter`: amount to convert. `Position`: position size.
 */
amount: Amount, 
/**
 * Price of one unit of the source asset. In `Position` mode this is the
 * entry price of the position.
 */
price_in: Amount, 
/**
 * `Converter` only: price of one unit of the target asset.
 */
price_out: Amount, 
/**
 * Take-profit price (`Position` only).
 */
target_price: Amount | null, 
/**
 * Stop-loss price (`Position` only).
 */
stop_price: Amount | null, 
/**
 * Round-trip commission in percent (`"0.1"` = 0.1%).
 */
fee_pct: Amount, };

/**
 * Which set of inputs/outputs [`preview`] should compute.
 */
type CalcMode = "converter" | "position";

/**
 * Ready-to-render result. Fields that do not apply to the chosen mode stay
 * zero; the UI shows an em dash for them.
 */
type CalcResult = { 
/**
 * `amount × price_in` — the notional put in.
 */
gross_in: Amount, 
/**
 * `gross_in × fee_pct / 100`.
 */
fee: Amount, 
/**
 * `gross_in + fee` — what the position really costs.
 */
spent: Amount, 
/**
 * `Converter`: `amount × price_out` before fees.
 */
gross_out: Amount, 
/**
 * `Converter`: `gross_out − fee`.
 */
net_out: Amount, 
/**
 * `Position`: `amount × target_price`.
 */
exit_value: Amount, 
/**
 * `Position`: `exit_value − spent`.
 */
pnl: Amount, 
/**
 * `Position`: `pnl / spent × 100`.
 */
roi_pct: Amount, 
/**
 * `Position`: `amount × (price_in − stop_price)`, floored at zero.
 */
risk: Amount, 
/**
 * `Position`: `risk / spent × 100`.
 */
risk_pct: Amount, };

